using System;using System.IO;using System.Linq;using System.Windows.Forms;using System.Threading.Tasks;
namespace LoopPedal {
sealed class PerformanceProject {
 public PerformanceScene State;public PerformanceScenes Scenes;
 public static PerformanceProject Capture(Engine[] banks){var result=new PerformanceProject{State=PerformanceScene.Capture(banks),Scenes=new PerformanceScenes()};lock(banks[0].Gate){for(int i=0;i<8;i++){result.Scenes.Slots[i]=banks[0].Scenes.Slots[i];result.Scenes.Names[i]=banks[0].Scenes.Names[i];}}var port=new PerformanceControl(result.State.Banks);var timeline=result.State.Timeline;for(int i=0;i<timeline.count;i++)port.set(timeline.lanes[i].target,timeline.lanes[i].audio,timeline.lanes[i].baseline);foreach(var m in timeline.mods)if(m.enabled)timeline.restore(port,m);for(int b=0;b<2;b++){var e=result.State.Banks[b];if(!e.WarpLayers&&e.Layers.Count>0){var l=e.Layers[0];e.LoopFrames=Math.Max(1,(int)(l.Original.Length/2*l.TrimLength*l.Stretch));}}return result;}
 public ulong Stamp(){using(var stream=new MemoryStream()){var d=new BinaryWriter(stream);State.Write(d,false);for(int i=0;i<8;i++){d.Write(Scenes.Names[i]);d.Write(Scenes.Slots[i]!=null);if(Scenes.Slots[i]!=null){d.Write(Scenes.Slots[i].Banks[0].Playing);d.Write(Scenes.Slots[i].Banks[1].Playing);Scenes.Slots[i].Write(d,false);}}d.Flush();ulong hash=14695981039346656037UL;foreach(byte b in stream.ToArray())hash=(hash^b)*1099511628211UL;return hash;}}
 public void Save(string path){string temp=path+".tmp";try{using(var file=File.Create(temp)){var d=new BinaryWriter(file);d.Write(0x41475731);State.Write(d,true);Scenes.Write(d);d.Flush();file.Flush(true);}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static PerformanceProject Load(string path){using(var stream=File.OpenRead(path)){var d=new BinaryReader(stream);if(d.ReadInt32()!=0x41475731)throw new IOException("Invalid Agent Looper project");return new PerformanceProject{State=PerformanceScene.Read(d),Scenes=PerformanceScenes.Read(d)};}}
}
sealed partial class Engine {
 public void ResetProject(){if(Recording)Finish(false);lock(Gate){foreach(var layer in Layers){if(layer.RenderCancellation!=null)layer.RenderCancellation.Cancel();if(layer.Stream!=null)RetireStream(layer.Stream);}Layers.Clear();undoStates.Clear();redoStates.Clear();CancelWarp();Frame=LoopOrigin=0;LoopFrames=0;Playing=PlaybackPending=false;Sync=AutoOverdub=WaitForInput=false;TriggerDb=-40;InputMode=StartQuantize=CountInBars=0;Bars=1;Destructive=true;DubFeedback=1;BPM=120;BeatsPerBar=BeatUnit=4;ClickDuringRecord=false;SingleLooper=true;gridSet=false;Fx.ResetDefaults();Fx.Plugins=null;}}
}
partial class Pedal {
 string projectPath;ulong cleanProject;bool projectClean,projectBusy;
 bool ProjectDirty(){return loopers.Any(b=>b.Recording)||!projectClean||PerformanceProject.Capture(loopers).Stamp()!=cleanProject;}
 async Task<bool> SaveProject(bool saveAs){try{EnsureNotRecording();if(projectBusy)return false;string path=projectPath;if(saveAs||path==null)using(var dialog=new SaveFileDialog{Filter="Agent Looper project|*.agw",FileName=path==null?"Untitled.agw":Path.GetFileName(path)}){if(dialog.ShowDialog(this)!=DialogResult.OK)return false;path=dialog.FileName;}var project=PerformanceProject.Capture(loopers);ulong stamp=project.Stamp();projectBusy=true;status.Text="Saving project…";await Task.Run(()=>project.Save(path));projectPath=path;cleanProject=stamp;projectClean=true;status.Text="Saved · "+Path.GetFileNameWithoutExtension(path);return true;}catch(Exception ex){status.Text=ex.Message;return false;}finally{projectBusy=false;}}
 async Task<bool> ReplaceGuard(){if(projectBusy)return false;if(!ProjectDirty())return true;var answer=MessageBox.Show(this,"Save changes to the current project?","Agent Looper",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(answer==DialogResult.No)return true;if(answer!=DialogResult.Yes)return false;if(!await SaveProject(false))return false;return !ProjectDirty()||await ReplaceGuard();}
 async void NewProject(){if(!await ReplaceGuard())return;foreach(var b in loopers)b.ResetProject();loopers[0].Performance=new PerformanceTimeline();loopers[0].Scenes=new PerformanceScenes();projectPath=null;SyncProjectUi();cleanProject=PerformanceProject.Capture(loopers).Stamp();projectClean=true;}
 async void LoadProject(){if(!await ReplaceGuard())return;using(var dialog=new OpenFileDialog{Filter="Agent Looper project|*.agw"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{EnsureNotRecording();projectBusy=true;status.Text="Loading project…";string path=dialog.FileName;var project=await Task.Run(()=>PerformanceProject.Load(path));var ready=await Task.Run(()=>project.State.Prepare());EnsureNotRecording();foreach(var bank in ready.Banks)bank.Fx.PreparePlugins();lock(loopers[0].Gate)lock(loopers[1].Gate){ready.Apply(loopers);loopers[0].Scenes=project.Scenes;foreach(var b in loopers)b.Playing=false;}projectPath=path;SyncProjectUi();cleanProject=PerformanceProject.Capture(loopers).Stamp();projectClean=true;status.Text="Loaded · "+Path.GetFileNameWithoutExtension(path);}catch(Exception ex){status.Text=ex.Message;}finally{projectBusy=false;}}}
 void ProjectItems(ToolStripItemCollection items){Item(items,"New project",NewProject);Item(items,"Save",async()=>{await SaveProject(false);});Item(items,"Save as…",async()=>{await SaveProject(true);});Item(items,"Load…",LoadProject);Item(items,"Import audio / video…",Import);Item(items,"Export WAV · "+(activeBank==0?"A":"B"),Export);}
}
}
